def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to remove build metadata
        v_without_build = v.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in v_without_build:
            core_part, prerelease_part = v_without_build.split('-', 1)
        else:
            core_part = v_without_build
            prerelease_part = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        # If no pre-release, it sorts after all versions with pre-release
        if identifiers is None:
            return (1, [])  # (1, ...) sorts after (0, ...)

        # Convert each identifier to a comparable form
        comparable = []
        for ident in identifiers:
            if ident.isdigit():
                # All-digit identifiers: (0, numeric_value)
                comparable.append((0, int(ident)))
            else:
                # Non-digit identifiers: (1, string_value)
                comparable.append((1, ident))

        return (0, comparable)  # (0, ...) sorts before (1, ...)

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        return (major, minor, patch, prerelease_key(prerelease_identifiers))

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

